style.css:
@-moz-document url-prefix("https://www.youtube.com") {
/*Font Changes*/
body,
p,
h2,
h3,
h4,
h5,
h6,
li,
a {
	font-family: 'Arial Black' !important;
	text-shadow: 3px 3px 5px rgba(0, 0, 0, 0.3);
}

span {
	font-family: 'Segoe UI' !important;
	text-shadow: 3px 3px 5px rgba(0, 0, 0, 0.3);
}
h1 {
	font-family: 'Arial Black' !important;
	text-shadow: 3px 3px 5px rgba(0, 0, 0, 0.3);
}

/*Ui Changes*/
badge-shape.badge-shape-wiz.badge-shape-wiz--thumbnail-default.badge-shape-wiz--thumbnail-badge {
	opacity: 0%;
}
ytd-mini-guide-entry-renderer.style-scope.ytd-mini-guide-renderer {
	opacity: 0%;
}
yt-button-shape {
	margin: 2px;
	backdrop-filter: blur(10px);
	/* Acrylic blur effect */
	border: 1px solid rgba(127, 127, 127, 0.1);
	/* Border with transparency (optional) */
	padding: 2px;
	/* Internal spacing */
	border-radius: 20px;
	/* Rounded border (optional) */
	box-shadow: 3px 3px 7px rgba(0, 0, 0, .2), -3px -3px 5px rgba(225, 225, 225, .2);
	transition: .1s linear;
}
yt-button-shape:hover {
	transform: scale(1.05);
}

ytd-masthead {
	margin-bottom: 3px;
	border: 1px solid rgba(127, 127, 127, 0);
	/* Border with transparency (optional) */
	padding: 0px;
	border-radius: 20px;
	filter: opacity(100%);
	backdrop-filter: blur(100px);
	box-shadow: 0 0 7px rgba(0, 0, 0, 0.3);
	transition: .1s linear;
}
ytd-masthead:hover {
	transform: scale(1.01)
}
yt-page-header-view-model {
	background: no-repeat url(https://i.imgur.com/VWG1F37.png);
	background-size: 24% 100%;
	backdrop-filter: blur(100px);
	top: 0%;
	left: 25%;
	box-shadow: -6px 0px 2px #ABACFF, 0px 0px 1px #F4D5FF, 0px 0px 1px #F4D5FF !important;
	border-top-right-radius: 120px;
	border-bottom-right-radius: 120px;
	border-top-left-radius: 55px;
	border-bottom-left-radius: 55px;
	border-color: #D6D0FF !important;
}
ytd-topbar-logo-renderer {
	background: no-repeat url(https://i.imgur.com/RuQMe4R.png);
	opacity: 1;
	width: 100% !important;
	height: 100% !important;
	background-size: 100% 80%;
	top: 0%;
	left: 25%;
	position: above;
	margin: 30px;
	padding: .2px;
	border-radius: 20px;
	/* Rounded border (optional) */
	transition: all 0.6;
}
ytd-topbar-logo-renderer:hover {
	transform: scale(1.002)
}
ytd-watch-flexy {
	border-radius: 20px;
	border: 1px solid rgba(127, 127, 127, 0);
	/* Border with transparency (optional) */
	backdrop-filter: blur(50px);
	filter: opacity(100%);
	transition: .2s linear;
	padding: 5px;
	margin-left: -135px;
}

ytd-video-owner-renderer {
	background: no-repeat url(https://i.imgur.com/VWG1F37.png);
	backdrop-filter: blur(100px);
	opacity: 1;
	width: 100% !important;
	height: 100% !important;
	background-size: 23% 100%;
	position: above;
	border-radius: 10px;
	border-color: #D6D0FF !important;
	box-shadow: -3px 0px 2px #ABACFF, 0px 0px 1px #F4D5FF, 0px 0px 1px #F4D5FF !important;
	transition: .1s linear;
}

ytd-video-owner-renderer:hover {
	transform: scale(1.04);
}

ytd-searchbox:hover {
	transform: scale(1.003);
	transition: .3s linear;
}
ytd-button-renderer.style-scope.ytd-masthead {
	opacity: 0%
}
yt-lockup-view-model {
	margin: 10px;
	width: 515px;
}
yt-lockup-view-model:hover {
	transform: scale(1.02);
	transition: .2s linear;
}

ytd-playlist-panel-renderer {
	width: 545px;
}
yt-reel-channel-bar-view-model {
	background: no-repeat url(https://i.imgur.com/VWG1F37.png);
	opacity: 1;
	width: 100% !important;
	height: 100% !important;
	background-size: 31% 100%;
	backdrop-filter: blur(3px);
	position: above;
	border-top-right-radius: 20px;
	border-bottom-right-radius: 20px;
	border-top-left-radius: 5px;
	border-bottom-left-radius: 5px;
	border-color: #D6D0FF !important;
	box-shadow: -3px 0px 1px #ABACFF, 0px 0px 1px #F4D5FF, 0px 0px 1px #F4D5FF !important;
	transition: .1s linear;
}
ytd-reel-shelf-renderer {
	width: 530px;
}
iron-selector {
	opacity: 0%;
	position: absolute;
}

/*Sec. 1, Squircle/Rounded Square Profile Pictures*/
.yt-user-photo .yt-thumb {
	border-radius: 15%;
	box-shadow: 0 0 15px rgba(0, 0, 0, 0.2);
}
.comment-simplebox-renderer .comment-author-thumbnail,
.comment-renderer-replybox .comment-author-thumbnail,
#guide-channels .video-thumb,
.yt-masthead-picker-body .video-thumb,
#yt-masthead-multilogin .video-thumb,
.comment-renderer .video-thumb,
.channel-header-profile-image-container,
.C6S3OU-nb-b .C6S3OU-nb-c img,
.C6S3OU-nb-e .C6S3OU-nb-c img {
	border-radius: 15%;
	box-shadow: 0 0 15px rgba(0, 0, 0, 0.2);
}
#yt-masthead-user .yt-masthead-user-icon {
	border-radius: 15%;
	box-shadow: 0 0 15px rgba(0, 0, 0, 0.2);
}
.yt-masthead-picker-photo-wrapper img {
	border-radius: 15%;
	box-shadow: 0 0 15px rgba(0, 0, 0, 0.2);
}
.yt-spec-avatar-shape__image-overlays,
.yt-spec-avatar-shape__image {
	border-radius: 15%;
	box-shadow: 0 0 15px rgba(0, 0, 0, 0.2);
}
.yt-author-thumbnail-button.style-scope.ytd-comment-view-model {
	border-radius: 15%;
	box-shadow: 0 0 15px rgba(0, 0, 0, 0.2);
}
img#img.style-scope.yt-img-shadow {
	border-radius: 15%;
	box-shadow: 0 0 15px rgba(0, 0, 0, 0.2);
}
yt-img-shadow,
#author-thumbnail {
	border-radius: 15% !important;
}
yt-img-shadow,
#avatar {
	border-radius: 35% !important;
	box-shadow: 3px 3px 5px rgba(0, 0, 0, .2), -3px -3px 15px rgba(225, 225, 225, .2);
}

/*Shadows*/
#avatar.ytd-shelf-renderer {
	border-radius: 15%;
}
yt-img-shadow.ytd-guide-entry-renderer {
	border-radius: 15%;
}
#avatar.ytd-video-owner-renderer {
	border-radius: 15%;
	margin: 5px;
}
#author-thumbnail.ytd-comment-simplebox-renderer {
	border-radius: 15%;
	margin: 5px;
}
#author-thumbnail.ytd-comment-renderer yt-img-shadow.ytd-comment-renderer {
	border-radius: 15%;
	margin: 5px;
}
#avatar.ytd-c4-tabbed-header-renderer {
	border-radius: 15%;
}
yt-img-shadow.ytd-mini-channel-renderer {
	border-radius: 15%;
}
yt-img-shadow.ytd-grid-channel-renderer {
	border-radius: 15%;
}
yt-img-shadow.ytd-topbar-menu-button-renderer {
	border-radius: 15%;
}
#avatar.ytd-active-account-header-renderer {
	border-radius: 15%;
}
